def relay_cycle_intervals(adjustments: list[int], cycle: int) -> int:
    frequencies = {0: 1}
    remainder = 0
    answer = 0
    for value in adjustments:
        remainder = (remainder + value) % cycle
        answer += frequencies.get(remainder, 0)
        frequencies[remainder] = frequencies.get(remainder, 0) + 1
    return answer

bruteForceSolution:
def relay_cycle_intervals(adjustments: list[int], cycle: int) -> int:
    answer = 0
    for start in range(len(adjustments)):
        total = 0
        for end in range(start, len(adjustments)):
            total += adjustments[end]
            if total % cycle == 0:
                answer += 1
    return answer
